#rStudioHeader .productName {
	color: #4254A7;
}

div.tagline {
	font-family: 'Libre Baskerville', serif !important;
	text-transform: uppercase;
	font-size: 1.2rem !important;
	font-weight: bold;
	letter-spacing: 2px;
}

#rStudioHeader #menu .menuItem:hover {
	background-color: white;
	color: #4254A7;
}

#TableOfContents a {
	font-family: 'Libre Baskerville';
	color: #00000075;
	transition: color 0.3s;
	font-size: 15px;
}

.sectionTitle, .sectionTitle a {
	text-transform: uppercase;
	letter-spacing: 2pt;
	font-size: 0.8rem !important;
	font-weight: bold;
	color: #4254A7;
}

h1, .article-title {
	font-family: 'Libre Baskerville', serif;
	color: #4254A7;
	font-weight: bold;
	font-size: 2em;
}

h2 {
	font-family: 'Libre Baskerville', serif;
	font-weight: bold;
	font-size: 1.25em;
}

.article-content ul li::before {
	content: "\2022";
	color: #f6b73c;
	font-weight: bold;
	display: inline-block;
	width: 1.5em;
	margin-left: -1.7em;
}

#rStudioFooter.band {
	background-color: #4254a730;
}
